<header class="admin-header"><div><span class="eyebrow">Moderation</span><h1>Discussions</h1></div></header><section class="admin-panel table-wrap"><table><thead><tr><th>Discussion</th><th>Author</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($discussions as $d):?><tr><td><strong><?=e($d['title'])?></strong><small><?=e($d['category'])?></small></td><td><?=e($d['full_name'])?></td><td><?=e($d['status'])?></td><td><form class="row-form" method="post" action="<?=url('admin/discussions/'.$d['id'])?>"><?=csrf_field()?><?=method_field('PUT')?><select name="status"><?php foreach(['draft','pending','published','hidden','locked'] as $s):?><option<?=selected($d['status'],$s)?>><?=e($s)?></option><?php endforeach;?></select><label><input name="is_pinned" type="checkbox" <?=$d['is_pinned']?'checked':''?>> Pinned</label><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></section>
